// Uma chamada por DIA (a API devolve todas as obras de uma vez quando obra_id e omitido).
// Backfill/recarga: preencha os dois campos abaixo com 'YYYY-MM-DD'.
// Os dois vazios = modo normal (ultimos DIAS dias, terminando hoje).
const DATA_INICIO = '';
const DATA_FIM = '';
const DIAS = 2; // hoje + ontem: o dia corrente ainda muda ate o fim do turno

const ISO = /^\d{4}-\d{2}-\d{2}$/;
const hoje = $now.setZone('America/Sao_Paulo').startOf('day');
const datas = [];

if (DATA_INICIO || DATA_FIM) {
  if (!ISO.test(DATA_INICIO) || !ISO.test(DATA_FIM)) {
    throw new Error('DATA_INICIO e DATA_FIM devem estar os dois preenchidos no formato YYYY-MM-DD');
  }
  let d = DateTime.fromISO(DATA_INICIO, { zone: 'America/Sao_Paulo' });
  const fim = DateTime.fromISO(DATA_FIM, { zone: 'America/Sao_Paulo' });
  if (fim < d) throw new Error('DATA_FIM e anterior a DATA_INICIO');
  while (d <= fim) { datas.push(d.toFormat('yyyy-MM-dd')); d = d.plus({ days: 1 }); }
} else {
  if (!(DIAS >= 1)) throw new Error('DIAS deve ser >= 1');
  for (let i = 0; i < DIAS; i++) datas.push(hoje.minus({ days: i }).toFormat('yyyy-MM-dd'));
}

return datas.map(data => ({ json: { data } }));

// Obras gravadas. null = TODAS as que a API devolver (hoje 21, inclui SEDE/AFASTADOS).
// Padrao = as 7 obras da tabela canonica painelmse.obras. Para incluir o
// CNPEM-AUDITORIO (que o fluxo antigo tinha comentado) e so acrescentar 103.
const OBRAS = [91, 94, 106, 107, 108, 110, 114];

const dataLoop = $('Loop data (1 por vez)').first().json.data;

// O node HTTP embrulha o corpo em { data: ... }; a propria API tambem responde { data: {...} }.
let corpo = $json;
if (typeof corpo === 'string') { corpo = JSON.parse(corpo); }
if (corpo && typeof corpo.data === 'string') { try { corpo = JSON.parse(corpo.data); } catch (e) { /* nao era JSON */ } }
while (corpo && corpo.data && typeof corpo.data === 'object' && !Array.isArray(corpo.data) && corpo.data.obras) { corpo = corpo.data; }
if (corpo && corpo.body && typeof corpo.body === 'object' && corpo.body.obras) { corpo = corpo.body; }

const vazio = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
const n = v => { if (vazio(v)) return null; const x = Number(typeof v === 'string' ? v.trim().replace(',', '.') : v); return Number.isFinite(x) ? x : null; };
const i = v => { const x = n(v); return x === null ? null : Math.trunc(x); };
const s = (v, max) => { if (vazio(v) || typeof v === 'object') return null; const t = String(v).trim(); return t.length > max ? t.slice(0, max) : t; };
const d = v => { if (vazio(v)) return null; const t = String(v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null; };
const q = String.fromCharCode(96);
const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\x00/g, '') + "'";
const sqlVal = (v) => (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? String(v) : escapar(v));

const dataRef = d(corpo && corpo.data_efetivo_diario) || d(dataLoop);
if (!dataRef) throw new Error('Sem data_efetivo_diario valida (loop: ' + dataLoop + ')');

const obras = corpo && Array.isArray(corpo.obras) ? corpo.obras : null;
if (!obras) {
  throw new Error('Formato inesperado em api_efetivo/efetivo para ' + dataRef + ' - chaves recebidas: ' + JSON.stringify(Object.keys(corpo || {})));
}

// Obra sem id_obra nao tem chave; obra fora de OBRAS nao interessa ao painel.
const obrasFiltradas = obras.filter(o => {
  const idObra = i(o.id_obra);
  if (idObra === null) return false;
  return OBRAS === null || OBRAS.includes(idObra);
});

const detalheMySql = [];
const detalheSupabase = [];
const resumoMySql = [];
const resumoSupabase = [];
const idsObras = [];
let vistos = 0;
let descartados = 0;
let amostraRuim = null;

for (const o of obrasFiltradas) {
  const idObra = i(o.id_obra);
  const nomeObra = s(o.nome_obra, 120);
  idsObras.push(idObra);

  const r = o.resumo || {};
  resumoMySql.push({
    data_efetivo_diario: dataRef,
    id_obra: idObra,
    nome_obra: nomeObra,
    is_hoje: corpo.is_hoje === true ? 1 : (corpo.is_hoje === false ? 0 : null),
    fonte: s(corpo.fonte, 60),
    total_obra: i(o.total),
    total: i(r.total),
    presentes: i(r.presentes),
    presentes_d: i(r.presentes_d),
    presentes_int: i(r.presentes_int),
    presentes_n: i(r.presentes_n),
    ausentes: i(r.ausentes),
    mobilizacao: i(r.mobilizacao),
    sede: i(r.sede),
    sem_atividade: i(r.sem_atividade),
    outros: i(r.outros)
  });

  // O Supabase (projeto Efetivo) mantem o nome de coluna antigo (obra_id) e a
  // coluna raw; o painel le essas duas tabelas hoje, nao dava pra renomear aqui.
  resumoSupabase.push({
    obra_id: idObra,
    nome_obra: nomeObra,
    data_efetivo_diario: dataRef,
    is_hoje: corpo.is_hoje ?? null,
    fonte: corpo.fonte ?? null,
    total_obra: o.total ?? null,
    total: r.total ?? null,
    presentes: r.presentes ?? null,
    presentes_d: r.presentes_d ?? null,
    presentes_int: r.presentes_int ?? null,
    presentes_n: r.presentes_n ?? null,
    ausentes: r.ausentes ?? null,
    mobilizacao: r.mobilizacao ?? null,
    sede: r.sede ?? null,
    sem_atividade: r.sem_atividade ?? null,
    outros: r.outros ?? null,
    raw: JSON.stringify(r)
  });

  const efetivo = Array.isArray(o.efetivo) ? o.efetivo : [];
  for (const f of efetivo) {
    vistos++;
    const idFunc = i(f.id_funcionario);
    const idEmp = i(f.id_empresa);
    // A chave no MySQL e no Supabase e (dia, obra, funcionario, empresa):
    // linha sem funcionario ou sem empresa nao tem onde encaixar.
    if (idFunc === null || idEmp === null) {
      descartados++;
      if (!amostraRuim) amostraRuim = JSON.stringify({ id_obra: idObra, funcionario: f }).slice(0, 400);
      continue;
    }
    detalheMySql.push({
      data_efetivo_diario: dataRef,
      id_obra: idObra,
      id_funcionario: idFunc,
      id_empresa: idEmp,
      nome_obra: nomeObra,
      nome: s(f.nome, 120),
      tipo_funcionario: s(f.tipo_funcionario, 40),
      moi_mod: s(f.moi_mod, 20),
      id_funcao: i(f.id_funcao),
      nome_funcao: s(f.nome_funcao, 120),
      razao_social: s(f.razao_social, 120),
      data_admissao: d(f.data_admissao),
      situacao: s(f.situacao, 40),
      observacao: vazio(f.observacao) ? null : String(f.observacao)
    });
    detalheSupabase.push({
      obra_id: idObra,
      nome_obra: nomeObra,
      data_efetivo_diario: dataRef,
      id_funcionario: idFunc,
      id_empresa: idEmp,
      tipo_funcionario: f.tipo_funcionario ?? null,
      moi_mod: f.moi_mod ?? null,
      nome: f.nome ?? null,
      id_funcao: f.id_funcao ?? null,
      nome_funcao: f.nome_funcao ?? null,
      razao_social: f.razao_social ?? null,
      data_admissao: d(f.data_admissao),
      situacao: f.situacao ?? null,
      observacao: f.observacao ?? null,
      raw: JSON.stringify(f)
    });
  }
}

// Sem isto, mapeamento errado vira carga vazia SEM erro: as linhas sao
// descartadas em silencio, o INSERT vira 'SELECT 1' e o fluxo termina verde.
if (vistos > 0 && detalheMySql.length === 0) {
  throw new Error('api_efetivo ' + dataRef + ': ' + vistos + ' funcionario(s) na resposta e NENHUM com id utilizavel. Amostra: ' + amostraRuim);
}

// Usa o alias `novo` no lugar de VALUES(col): VALUES() esta deprecado no
// MySQL 8.4 e enche o log de warning 1287 (1 por coluna, por statement).
const montarUpsert = (tabela, colunas, chave, linhas) => {
  if (!linhas.length) return 'SELECT 1';
  const cols = colunas.map(c => q + c + q).join(',');
  const tuplas = linhas.map(l => '(' + colunas.map(c => sqlVal(l[c])).join(',') + ')').join(',\n');
  const upd = colunas.filter(c => !chave.includes(c)).map(c => q + c + q + ' = novo.' + q + c + q).join(', ');
  return 'INSERT INTO ' + tabela + ' (' + cols + ') VALUES ' + tuplas + ' AS novo ON DUPLICATE KEY UPDATE ' + upd;
};

const COLS_DETALHE = ['data_efetivo_diario','id_obra','id_funcionario','id_empresa','nome_obra','nome','tipo_funcionario','moi_mod','id_funcao','nome_funcao','razao_social','data_admissao','situacao','observacao'];
const COLS_RESUMO = ['data_efetivo_diario','id_obra','nome_obra','is_hoje','fonte','total_obra','total','presentes','presentes_d','presentes_int','presentes_n','ausentes','mobilizacao','sede','sem_atividade','outros'];

const sqlDetalhe = montarUpsert('efet_diario', COLS_DETALHE, ['data_efetivo_diario','id_obra','id_funcionario','id_empresa'], detalheMySql);
const sqlResumo = montarUpsert('efet_resumo_diario', COLS_RESUMO, ['data_efetivo_diario','id_obra'], resumoMySql);

// Quem saiu do efetivo do dia tem que sair da tabela. So apaga dentro das obras
// que vieram nesta resposta: resposta vazia (API fora do ar, dia sem lancamento)
// nao apaga nada, porque idsObras fica vazio.
let sqlDeleteDetalhe = 'SELECT 1';
let sqlDeleteResumo = 'SELECT 1';
if (idsObras.length) {
  const listaObras = idsObras.join(',');
  const escopo = 'data_efetivo_diario = ' + sqlVal(dataRef) + ' AND id_obra IN (' + listaObras + ')';
  const trincas = detalheMySql.map(r => '(' + r.id_obra + ',' + r.id_funcionario + ',' + r.id_empresa + ')').join(',');
  sqlDeleteDetalhe = trincas
    ? 'DELETE FROM efet_diario WHERE ' + escopo + ' AND (id_obra, id_funcionario, id_empresa) NOT IN (' + trincas + ')'
    : 'DELETE FROM efet_diario WHERE ' + escopo;
  // Resumo: 1 linha por obra, e toda obra do escopo acabou de ser reinserida.
  // Este DELETE so serve pra limpar obra que saiu de OBRAS depois de ja ter sido gravada.
  sqlDeleteResumo = 'DELETE FROM efet_resumo_diario WHERE data_efetivo_diario = ' + sqlVal(dataRef) + ' AND id_obra NOT IN (' + listaObras + ')';
}

const diagnostico = {
  data_efetivo_diario: dataRef,
  obras_na_resposta: obras.length,
  obras_gravadas: obrasFiltradas.length,
  funcionarios_recebidos: vistos,
  descartados: descartados,
  linhas_detalhe: detalheMySql.length,
  linhas_resumo: resumoMySql.length
};

return [{
  json: {
    detalheSupabase,
    resumoSupabase,
    sqlDetalhe,
    sqlResumo,
    sqlDeleteDetalhe,
    sqlDeleteResumo,
    diagnostico
  }
}];
